  function readCandyRaw() {
    try {
      const raw = localStorage.getItem(CANDY_KEY);
      return raw ? JSON.parse(raw) : {};
    } catch { return {}; }
  }
  function writeCandy(map) {
    localStorage.setItem(CANDY_KEY, JSON.stringify(map));
  }
